(() => {'use strict';const code=new URLSearchParams(location.search).get('member'),member=window.SahaReservationCatalog.team.find(m=>m.code===code);if(!member){document.getElementById('member-name').textContent='عضو تیم پیدا نشد';document.getElementById('member-future').hidden=true;return;}document.title=member.name+' | تیم سها';document.getElementById('member-name').textContent=member.name;document.getElementById('member-role').textContent=member.role;document.getElementById('member-bio').textContent=member.bio||'';})();
